node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// 1. Remove Northline Wool Blend Throw Blanket (CI-0011, PROD-FA349F)
db.prepare('DELETE FROM cart_items WHERE cart_item_id = ?').run('CI-0011');

// 2. Update CableCraft USB-C Organizer Strap 2-Pack (CI-0012) quantity to 2
db.prepare('UPDATE cart_items SET quantity = 2 WHERE cart_item_id = ?').run('CI-0012');

// 3. Recompute cart totals
// Remaining items: CI-0010 (PROD-FA0948, qty 1), CI-0012 (PROD-7583E5, qty 2)
const items = db.prepare('SELECT ci.*, p.price, p.name FROM cart_items ci JOIN products p ON ci.product_id = p.product_id WHERE ci.customer_id = ?').all('user_fbab7801');
console.log('=== Updated Cart Items ===');
items.forEach(i => console.log(JSON.stringify(i)));

let subtotal = 0;
let totalItemCount = 0;
items.forEach(i => { subtotal += i.price * i.quantity; totalItemCount += i.quantity; });

const newItemIds = items.map(i => i.cart_item_id);
const shippingCost = totalItemCount >= 5 ? 0 : 6; // standard shipping
const total = subtotal + shippingCost;

db.prepare('UPDATE carts SET item_ids_json = ?, subtotal = ?, shipping_cost = ?, total = ? WHERE cart_id = ?')
  .run(JSON.stringify(newItemIds), subtotal, shippingCost, total, 'CART-user_fbab7801');

// Verify
const cart = db.prepare('SELECT * FROM carts WHERE cart_id = ?').get('CART-user_fbab7801');
console.log('\n=== Updated Cart ===');
console.log(JSON.stringify(cart, null, 2));

db.close();
"
